<form class="card knowledge-filters" method="get" action="/knowledge"><label>Search<input type="search" name="q" maxlength="200" value="<?= e($q) ?>" placeholder="Title or note text"></label><label>Notebook<select name="notebook"><option value="">All notebooks</option><?php foreach ($notebooks as $name): ?><option value="<?= e($name) ?>" <?= $notebook===$name?'selected':'' ?>><?= e($name) ?></option><?php endforeach; ?></select></label><label>Tag<select name="tag"><option value="">All tags</option><?php foreach ($allTags as $name): ?><option value="<?= e($name) ?>" <?= $tag===$name?'selected':'' ?>><?= e($name) ?></option><?php endforeach; ?></select></label><label>View<select name="state"><option value="active" <?= $state==='active'?'selected':'' ?>>Active</option><option value="archived" <?= $state==='archived'?'selected':'' ?>>Archived</option><option value="trash" <?= $state==='trash'?'selected':'' ?>>Trash</option></select></label><label>Sort<select name="sort"><option value="recent" <?= $sort==='recent'?'selected':'' ?>>Recently updated</option><option value="title" <?= $sort==='title'?'selected':'' ?>>Title</option></select></label><button class="secondary">Apply</button></form>
