<div class="knowledge-grid"><?php foreach ($rows as $note): ?><article class="card knowledge-card"><div class="knowledge-meta"><span><?= e($note['notebook']) ?></span><?php if ($note['pinned']): ?><span>📌 Pinned</span><?php endif; ?><?php if ($note['archived']): ?><span>Archived</span><?php endif; ?></div><h2><a href="/knowledge/<?= e($note['id']) ?>"><?= e($note['title']) ?></a></h2><p><?= e(mb_substr(preg_replace('/\s+/u',' ',$note['body']) ?? '',0,170)) ?></p><div class="knowledge-tags"><?php foreach (array_filter(array_map('trim',explode(',',$note['tags']))) as $tagName): ?><a href="/knowledge?tag=<?= rawurlencode($tagName) ?>"><?= e($tagName) ?></a><?php endforeach; ?></div><small>Updated <?= e($note['updated_at']) ?></small></article><?php endforeach; ?></div>
